using UnityEngine;
using UnityEngine.InputSystem;
namespace CoopBeam {
// All offensive bonuses modify the cooperative segment, never an individual weapon.
public class LinkPowers:MonoBehaviour {
 public float Charge{get;private set;} public const float ChargeRequired=180;
 public bool Ultimate=>Time.time<ultimateUntil; public bool Empowered=>Ultimate||Time.time<prismUntil;
 public float DamageMultiplier=>Ultimate?2.4f:Time.time<prismUntil?1.5f:1;
 public bool ChainActive=>Time.time<chainUntil;public bool SolarActive=>Time.time<solarUntil;public int ChainHits{get;private set;}public int SolarHits{get;private set;}
 public string Status{get;private set;}="DANO DEL LAZO CARGA RESONANCIA";
 public int UltimatesUsed{get;private set;} public int PickupsCollected{get;private set;}
 static float carriedCharge;
 public bool ActiveBonus=>Time.time<prismUntil||ChainActive||SolarActive||(Time.time<shieldUntil&&(shields[0]||shields[1]));
 public float NextLootAt{get;private set;}
 int eligibleKills;
 public bool CanDrop=>!ActiveBonus&&Time.time>=NextLootAt&&(!GetComponent<CoopInteractionDirector>()||!GetComponent<CoopInteractionDirector>().HasPending)&&FindObjectsByType<LinkPickup>().Length==0;
 GameManager game;float ultimateUntil,prismUntil,shieldUntil,chainUntil,solarUntil,chainAt,solarAt,moraReady=-10,limaReady=-10,fxAt,statusUntil;int kills,dropIndex;bool[] shields=new bool[2];
 void Awake(){game=GetComponent<GameManager>();Charge=Mathf.Min(ChargeRequired,carriedCharge);NextLootAt=Time.time+4;}
 void Start(){var beam=FindAnyObjectByType<CoopBeam>();if(beam&&!beam.GetComponent<ResonanceVisual>())beam.gameObject.AddComponent<ResonanceVisual>();}
 public void AddCharge(float damage){if(game.Running&&!Ultimate&&damage>0){Charge=Mathf.Min(ChargeRequired,Charge+damage);if(!game.Practice)carriedCharge=Charge;}}
 public void OnKill(Vector3 position){kills++;if(!CanDrop)return;if(++eligibleKills<3)return;eligibleKills=0;var cycle=new[]{LinkPickup.Kind.Prism,LinkPickup.Kind.Chain,LinkPickup.Kind.Shield,LinkPickup.Kind.Solar,LinkPickup.Kind.Heart};var drop=LinkPickup.Create(position,cycle[dropIndex%cycle.Length]);if(drop){dropIndex++;drop.owner=this;NextLootAt=Time.time+8;}}
 public bool Absorb(PlayerHealth player){if(Time.time>=shieldUntil)return false;for(int i=0;i<game.players.Length&&i<2;i++)if(game.players[i]==player&&shields[i]){shields[i]=false;BeamFX.Burst(player.transform.position,Color.cyan,14);return true;}return false;}
 public bool HasShield(int i)=>Time.time<shieldUntil&&shields[i];
 public void Collect(LinkPickup.Kind kind){var director=GetComponent<CoopInteractionDirector>();if(director){director.Receive(kind);return;}ApplyShared(kind);}
 public void ApplyShared(LinkPickup.Kind kind){if(!game.Running||ActiveBonus)return;PickupsCollected++;prismUntil=chainUntil=solarUntil=shieldUntil=0;shields[0]=shields[1]=false;NextLootAt=Time.time+(kind==LinkPickup.Kind.Shield?22:kind==LinkPickup.Kind.Heart?10:kind==LinkPickup.Kind.Prism?15:17);if(kind==LinkPickup.Kind.Prism){prismUntil=Time.time+8;Message("PRISMA / DANO DEL LAZO X1.5");}else if(kind==LinkPickup.Kind.Shield){shieldUntil=Time.time+15;shields[0]=shields[1]=true;Message("BURBUJA / PROTECCION PARA AMBOS");}else if(kind==LinkPickup.Kind.Chain){chainUntil=Time.time+10;Message("CHISPA / EL LAZO ENCADENA ENEMIGOS");}else if(kind==LinkPickup.Kind.Solar){solarUntil=Time.time+10;solarAt=Time.time+.4f;Message("ANILLO / PULSOS ALREDEDOR DEL LAZO");}else{foreach(var h in game.players)if(!h.Dead)h.Heal();AddCharge(30);Message("CORAZON / +1 VIDA Y RESONANCIA");}game.Tone(1080,.18f);}
 bool Linked=>game&&game.Running&&!game.players[0].Dead&&!game.players[1].Dead&&((Vector2)(game.players[0].transform.position-game.players[1].transform.position)).sqrMagnitude>.0025f;
 public static Vector2 TargetPoint(EnemyBase enemy){var fire=enemy.GetComponent<FireForgeBoss>();if(fire)return fire.core.transform.position;var ice=enemy.GetComponent<IceKingBoss>();if(ice)return ice.core.transform.position;var candy=enemy.GetComponent<CandyBoss>();return candy?(Vector2)candy.weakSpot.transform.position:(Vector2)enemy.transform.position;}
 public void OnBeamHit(EnemyBase source,float acceptedDamage){if(!ChainActive||!Linked||acceptedDamage<=0||Time.time<chainAt)return;chainAt=Time.time+.8f;Vector2 point=TargetPoint(source);int count=0;foreach(var enemy in game.enemies.ToArray()){if(!enemy||enemy==source||enemy.Dead||Vector2.Distance(point,TargetPoint(enemy))>3.5f)continue;float hp=enemy.Health;enemy.Damage(10);LinkArcFX.Spawn(point,TargetPoint(enemy),new Color(1,.7f,.12f));if(enemy.Health<hp)ChainHits++;if(++count>=2)break;}}
 void SolarPulse(){if(!SolarActive||!Linked||Time.time<solarAt)return;solarAt=Time.time+1.4f;Vector2 a=game.players[0].transform.position,b=game.players[1].transform.position;LinkArcFX.Pulse(a,b);foreach(var enemy in game.enemies.ToArray()){if(!enemy||enemy.Dead||Distance(TargetPoint(enemy),a,b)>.95f)continue;float hp=enemy.Health;enemy.Damage(18);if(enemy.Health<hp)SolarHits++;}}
 public void Message(string text){Status=text;statusUntil=Time.time+4;}
 public static void ResetStoredCharge(){carriedCharge=0;}
 public bool IsConfirmed(int player)=>player==0?moraReady>=0:limaReady>=0;
 public void ResetConfirmations(){moraReady=limaReady=-10;}
 public bool Confirm(int player){if(player<0||player>1||!game.Running||Time.timeScale<=0||GetComponent<CoopInteractionDirector>()&&GetComponent<CoopInteractionDirector>().Dancing||Charge<ChargeRequired||game.players[0].Dead||game.players[1].Dead)return false;var coop=GetComponent<CoopInteractionDirector>();if(coop&&coop.TutorialOpen)return false;if(player==0)moraReady=Time.time;else limaReady=Time.time;
  if(moraReady<0||limaReady<0)return false;Charge=0;if(!game.Practice)carriedCharge=0;var director=GetComponent<CoopInteractionDirector>();if(director){var modes=GetComponent<CoopUltimateModes>();director.BeginDance();moraReady=limaReady=-10;return true;}ultimateUntil=Time.time+4.5f;UltimatesUsed++;moraReady=limaReady=-10;foreach(var h in game.players){h.Protect(.75f);BeamFX.Burst(h.transform.position,Color.cyan,24);}Message("RESONANCIA! CRUCEN EL LAZO");game.Tone(1320,.3f);return true;}
 void Update(){if(!game.Running){moraReady=limaReady=-10;return;}if(Time.timeScale<=0)return;if(!Ultimate&&!game.players[0].Dead&&!game.players[1].Dead)AddCharge(Time.deltaTime*5);var k=Keyboard.current;if(k!=null){if(k.qKey.wasPressedThisFrame)Confirm(0);if(k.rightShiftKey.wasPressedThisFrame)Confirm(1);}if(Time.time>statusUntil)Status=Ultimate?"RESONANCIA ACTIVA":Charge>=ChargeRequired?(moraReady>=0?"MIMO LISTA / PIPRO: SHIFT DER":limaReady>=0?"PIPRO LISTA / MIMO: Q":"ULTI LISTA / Q + SHIFT DER"):"DANO DEL LAZO CARGA RESONANCIA";
  if(CoopInteractionDirector.Active&&CoopInteractionDirector.Active.Dancing)return;SolarPulse();if(!Ultimate||!Linked||Time.time<fxAt)return;fxAt=Time.time+.07f;Vector3 a=game.players[0].transform.position,b=game.players[1].transform.position;BeamFX.Burst(Vector3.Lerp(a,b,Random.value),CoopPresentation.PlayerColor(Random.value>.5f?0:1),3);
  foreach(var p in FindObjectsByType<CandyProjectile>())if(Distance(p.transform.position,a,b)<.45f){BeamFX.Burst(p.transform.position,Color.white,3);Destroy(p.gameObject);}foreach(var p in FindObjectsByType<EncounterHazard>())if(p.clearable&&p.Active&&Distance(p.transform.position,a,b)<.45f)p.Clear();
 }
 public void FinishDance(){ultimateUntil=Time.time+8;UltimatesUsed++;}
 void OnDestroy(){if(game&&!game.Practice&&game.Started&&!game.Running&&!game.Victory)carriedCharge=0;}
 public static float Distance(Vector2 point,Vector2 a,Vector2 b){var d=b-a;return Vector2.Distance(point,a+d*Mathf.Clamp01(Vector2.Dot(point-a,d)/Mathf.Max(.0001f,d.sqrMagnitude)));}
 void OnGUI(){if(!game||!game.Running)return;GUI.depth=-1;PixelFont.Begin();var cyan=new Color(.25f,.85f,1);bool charged=Charge>=ChargeRequired;PixelFont.Panel(new Rect(8,40,378,33),PixelFont.Ink,cyan);PixelFont.Fill(new Rect(16,46,362,7),new Color(.08f,.2f,.3f));PixelFont.Fill(new Rect(16,46,362*Charge/ChargeRequired,7),cyan);PixelFont.Text(16,59,charged?("ULTI / MIMO Q "+(IsConfirmed(0)?"OK":"?")+" / PIPRO SHIFT DER "+(IsConfirmed(1)?"OK":"?")):"SUPER PODER "+Mathf.RoundToInt(100*Charge/ChargeRequired)+"%",1,cyan);if(charged)for(int i=0;i<7;i++){float boltX=24+i*53,y=43+Mathf.Sin(Time.unscaledTime*9+i)*2;CoopPromptUI.Line(new Vector2(boltX,y),new Vector2(boltX-4,y+7),2,Color.white);CoopPromptUI.Line(new Vector2(boltX-4,y+7),new Vector2(boltX+3,y+6),2,cyan);CoopPromptUI.Line(new Vector2(boltX+3,y+6),new Vector2(boltX-2,y+13),2,Color.white);}PixelFont.Panel(new Rect(394,40,238,33),PixelFont.Ink,PixelFont.Mint);string message=Status.Length>37?Status.Substring(0,37):Status;PixelFont.Text(402,47,message,1,PixelFont.Cream);float x=402;EffectIcon(ref x,LinkPickup.Kind.Prism,prismUntil);EffectIcon(ref x,LinkPickup.Kind.Chain,chainUntil);EffectIcon(ref x,LinkPickup.Kind.Solar,solarUntil);if(HasShield(0)||HasShield(1))EffectIcon(ref x,LinkPickup.Kind.Shield,shieldUntil);}
 void EffectIcon(ref float x,LinkPickup.Kind kind,float until){if(Time.time>=until)return;var icon=ExpansionSprites.Icon((int)kind);GUI.color=Color.white;GUI.DrawTextureWithTexCoords(new Rect(x,58,12,12),icon.texture,new Rect(icon.rect.x/icon.texture.width,icon.rect.y/icon.texture.height,icon.rect.width/icon.texture.width,icon.rect.height/icon.texture.height));PixelFont.Text(x+15,61,Mathf.CeilToInt(until-Time.time)+"S",1,LinkPickup.ColorFor(kind));x+=55;}
}
}
